CREATE TRIGGER [stripe].trgUpdateinvoice
ON [stripe].[invoice]
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE
        [stripe].[invoice]
    SET
        __mj_UpdatedAt = GETUTCDATE()
    FROM
        [stripe].[invoice] AS _organicTable
    INNER JOIN
        INSERTED AS I ON
        _organicTable.[id] = I.[id];
END;
